WITH prev AS (SELECT pain_point, COUNT(DISTINCT respondent_id) * 1.0 / (SELECT COUNT(*) FROM respondents) as prevalence, AVG(pain_severity) as severity FROM pain_points GROUP BY pain_point) SELECT pain_point, ROUND(prevalence*100, 2) as prevalence_pct, ROUND(severity, 2) as avg_severity, ROUND(prevalence*severity*100, 2) as priority_score, RANK() OVER(ORDER BY prevalence*severity DESC) as rank FROM prev;
